 */
function evaluateProperty({
    api,
    helpers
}) {
    const sys_id = api.state.chat_setup.sys_id;
    const connectLink = api.data.settings.output ? api.data.settings.output.connectLink : null;
    if (!sys_id || !connectLink)
        return [];
    else     
        return [{
            "label": connectLink.label || '',
            "value": {
                "href": connectLink.url + sys_id
            },
            "type": "external",
            "endsWith": {
                "type": "icon",
                "value": "clipboard-outline",
                "size": "sm",
                "additionalAttrs": {
                    "size": "sm"
                }
            },

            "opensWindow": false,
            "configAria": {},
            "download": false,
        }];
}

